import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2023-02-07","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2023-02-07","date":"2023-02-07T00:00:00.000Z","updated":"2023-02-08T00:00:00.000Z","tags":["Ceph","Keepalived","High Availability","Manager","Virtual IP"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Orchestrator_Meeting_2023-02-07.md","filePath":"posts/2023/Ceph_Orchestrator_Meeting_2023-02-07.md","lastUpdated":1780460162000}'),r={name:"posts/2023/Ceph_Orchestrator_Meeting_2023-02-07.md"};function o(s,e,n,p,h,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议主要讨论了Ceph存储系统中管理器（manager）的高可用性（HA）实现，特别是通过使用keepalived来管理虚拟IP（Virtual IP）的问题。会议中涉及了多个技术细节和潜在的解决方案，以及后续的行动计划。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Keepalived与管理器集成</strong>：</p><ul><li>讨论了如何使用keepalived为管理器提供一个稳定的虚拟IP，以便外部Prometheus实例可以稳定地抓取数据。</li><li>探讨了管理器是否需要绑定到特定的IP地址，以及如何处理管理器故障转移时IP的变化。</li></ul></li><li><p><strong>构建错误问题</strong>：</p><ul><li>提到了一些构建错误尚未解决，特别是在Sepia Slack上有相关的讨论和拉取请求（pull request），但问题仍未完全解决。</li></ul></li><li><p><strong>动态绑定问题</strong>：</p><ul><li>讨论了是否可以在运行时动态绑定到新的虚拟IP，以及如何处理绑定失败的情况。</li></ul></li><li><p><strong>健康检查</strong>：</p><ul><li>讨论了如何实现管理器的健康检查，以便keepalived可以正确地识别和管理管理器的状态。</li></ul></li><li><p><strong>与Dashboard和Prometheus的集成</strong>：</p><ul><li>讨论了如何将虚拟IP的信息传递给Dashboard和Prometheus，并确保它们能够正确地使用这个IP。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ol><li><p><strong>研究与验证</strong>：</p><ul><li>需要进一步研究管理器的绑定机制，以及是否可以动态绑定到新的虚拟IP。</li><li>需要验证keepalived的健康检查脚本是否可以正确地识别管理器的状态。</li></ul></li><li><p><strong>行动计划</strong>：</p><ul><li>下周将再次讨论这些问题，届时将会有更多的研究和验证结果。</li><li>需要编写文档，指导用户在升级时如何处理keepalived机制。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><p><strong>研究与验证</strong>：</p><ul><li>验证管理器是否可以动态绑定到新的虚拟IP。</li><li>验证keepalived的健康检查脚本是否可以正确地识别管理器的状态。</li></ul></li><li><p><strong>编写文档</strong>：</p><ul><li>编写详细的文档，指导用户在升级时如何处理keepalived机制。</li></ul></li><li><p><strong>下周会议</strong>：</p><ul><li>下周将再次讨论这些问题，届时将会有更多的研究和验证结果。</li></ul></li></ol><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>本次会议主要集中在Ceph管理器的高可用性实现上，特别是通过keepalived管理虚拟IP的问题。会议中提出了多个技术挑战和潜在的解决方案，并制定了后续的研究和验证计划。下周将再次讨论这些问题，届时将会有更多的研究和验证结果。</p>',11)])])}const _=l(r,[["render",o]]);export{c as __pageData,_ as default};
